  | 'other'

export type Block = {
  readonly id: string
  readonly from: number
  readonly to: number
  readonly text: string
  readonly kind: BlockKind
  readonly level?: number
}

type MarkdownTree = ReturnType<typeof markdownLanguage.parser.parse>

type Classification = {
  readonly kind: BlockKind
  readonly level?: number
}

const HEADING_NODE = /^(?:ATX|Setext)Heading([1-6])$/

const SIMPLE_KINDS: Readonly<Record<string, BlockKind>> = {
  Paragraph: 'paragraph',
  BulletList: 'list',
  OrderedList: 'list',
  Blockquote: 'blockquote',
  FencedCode: 'code',
  CodeBlock: 'code',
  Table: 'table',
  HTMLBlock: 'html',
  HorizontalRule: 'rule',
}

const classify = (nodeName: string): Classification => {
  const heading = HEADING_NODE.exec(nodeName)
  if (heading?.[1]) return { kind: 'heading', level: Number(heading[1]) }
  return { kind: SIMPLE_KINDS[nodeName] ?? 'other' }
}

export const extractBlocksFromTree = (
  tree: MarkdownTree,
  text: string,
): readonly Block[] => {
  const blocks: Block[] = []
  for (
    let node = tree.topNode.firstChild;
    node !== null;
    node = node.nextSibling
  ) {
    blocks.push({
      id: `p${blocks.length + 1}`,
      from: node.from,
      to: node.to,
      text: text.slice(node.from, node.to),
      ...classify(node.name),
    })
  }
  return blocks
}

export const extractBlocks = (text: string): readonly Block[] =>
  extractBlocksFromTree(markdownLanguage.parser.parse(text), text)
import type { Block } from './extract-blocks'

export type Selection = {
  readonly from: number
  readonly to: number
}

export type Target = {
  readonly source: 'selection' | 'block'
  readonly from: number
  readonly to: number
  readonly text: string
  readonly blocks: readonly Block[]
}

export type Neighbors = {
  readonly title?: string
  readonly section?: string
  readonly before: readonly Block[]
  readonly after: readonly Block[]
}

const NEIGHBOR_COUNT = 2

export const findBlockAt = (
  blocks: readonly Block[],
  position: number,
): Block | undefined =>
  blocks.find((block) => block.from <= position && position <= block.to)

const distanceTo = (block: Block, position: number): number =>
  position < block.from ? block.from - position : position - block.to

const nearestBlock = (
  blocks: readonly Block[],
  position: number,
): Block | undefined =>
  blocks.reduce<Block | undefined>(
    (best, block) =>
      best === undefined ||
      distanceTo(block, position) < distanceTo(best, position)
        ? block
        : best,
    undefined,
  )

export const headingText = (block: Block): string => {
  const lines = block.text.split('\n')
  const content = lines[0]?.startsWith('#')
    ? lines[0].replace(/^#{1,6}[ \t]*/, '').replace(/[ \t]+#+[ \t]*$/, '')
    : lines.slice(0, -1).join(' ')
  return content.trim()
}

const overlaps = (block: Block, from: number, to: number): boolean =>
  block.from < to && block.to > from

const resolveSelectionTarget = (
  blocks: readonly Block[],
  text: string,
  { from, to }: Selection,
): Target | undefined => {
  const selected = text.slice(from, to)
  if (selected.trim() === '') return undefined
  return {
    source: 'selection',
    from,
    to,
    text: selected,
    blocks: blocks.filter((block) => overlaps(block, from, to)),
  }
}

const resolveCursorTarget = (
  blocks: readonly Block[],
  position: number,
): Target | undefined => {
  const block = findBlockAt(blocks, position) ?? nearestBlock(blocks, position)
  return block === undefined
    ? undefined
    : {
        source: 'block',
        from: block.from,
        to: block.to,
        text: block.text,
        blocks: [block],
      }
}

export const resolveTarget = (
  blocks: readonly Block[],
  text: string,
  selection: Selection,
): Target | undefined => {
  const from = Math.max(0, Math.min(selection.from, selection.to))
  const to = Math.min(text.length, Math.max(selection.from, selection.to))
  return from === to
    ? resolveCursorTarget(blocks, from)
    : resolveSelectionTarget(blocks, text, { from, to })
}

const anchorRange = (target: Target): Selection => ({
  from: Math.min(target.from, ...target.blocks.map((block) => block.from)),
  to: Math.max(target.to, ...target.blocks.map((block) => block.to)),
})

export const getNeighbors = (
  blocks: readonly Block[],
  target: Target,
): Neighbors => {
  const { from, to } = anchorRange(target)
  const preceding = blocks.filter((block) => block.to <= from)
  const following = blocks.filter((block) => block.from >= to)
  const title = blocks.find(
    (block) => block.kind === 'heading' && block.level === 1,
  )
  const section = preceding.findLast((block) => block.kind === 'heading')
  return {
    ...(title && { title: headingText(title) }),
    ...(section && { section: headingText(section) }),
    before: preceding.slice(-NEIGHBOR_COUNT),
    after: following.slice(0, NEIGHBOR_COUNT),
  }
}

# Slice 2 verification: model client and Bake-off

Issue [#2](https://github.com/walteraandrade/chiri-ai-editor/issues/2). This slice has no UI, so the checks are a captured request body, one call through the Vite proxy from a real browser, and the Bake-off.

## Strict structured output: confirmed

`@openrouter/ai-sdk-provider@3.1.0` sends a strict JSON schema for both `Output.object` and `Output.array`, so the fallback `@ai-sdk/openai-compatible` is not needed and [ADR 0009](../adr/0009-ai-sdk-v7.md) stands.

The tests in `src/ai/client.test.ts` inject a `fetch` that captures the request body (no network). A Target request (`Output.object` with `suggestionSchema`) sends:

```json
{
  "model": "vendor/model-a",
  "response_format": {
    "type": "json_schema",
    "json_schema": {
      "schema": {
        "$schema": "http://json-schema.org/draft-07/schema#",
        "type": "object",
        "properties": {
          "replacement": { "type": "string", "description": "The new text that replaces the Target, in Markdown, in the language of the Target." },
          "rationale": { "type": "string", "description": "One short sentence explaining the change, in the language of the Document." }
        },
        "required": ["replacement", "rationale"],
        "additionalProperties": false
      },
      "strict": true,
      "name": "response"
    }
  },
  "messages": [{ "role": "system", "content": [{ "type": "text", "text": "…" }] }, { "role": "user", "content": "…" }],
  "reasoning": { "effort": "low" },
  "provider": { "require_parameters": true }
}
```

The Review pass (`Output.array` + `streamText`) sends the same envelope with `"stream": true` and this schema. The SDK owns the array wrapper, so the wire shape is `{ "elements": [...] }`, not the `{ "edits": [...] }` of [ADR 0002](../adr/0002-structured-output-app-owned-anchors.md):

```json
{
  "type": "object",
  "properties": {
    "elements": {
      "type": "array",
      "items": {
        "type": "object",
        "properties": { "blockId": { "type": "string" }, "replacement": { "type": "string" }, "rationale": { "type": "string" } },
        "required": ["blockId", "replacement", "rationale"],
        "additionalProperties": false
      }
    }
  },
  "required": ["elements"],
  "additionalProperties": false
}
```

Where the settings come from, read in the provider source (`dist/index.js`, `getArgs`): `provider` and `reasoning` are model settings (`provider.chat(model, { provider: { require_parameters: true }, structuredOutputs: { strict: true }, reasoning: { effort: 'low' } })`). `strict` already defaults to `true`; the client sets it anyway. The same keys also work through `providerOptions.openrouter`, which the provider spreads into the body.

