    expect(result.hunks.filter((hunk) => hunk.type === 'inserted')).toHaveLength(1)
    expect(result.hunks.find((hunk) => hunk.type === 'deleted')?.text).toBe('foo bar')
    expect(result.hunks.find((hunk) => hunk.type === 'inserted')?.text).toBe('alpha beta')
  })

  it('always puts the deleted hunk before the inserted hunk of a change', () => {
    const result = adaptiveDiff(
      `${words(20, 'keep')} old ${words(20, 'tail')}`,
      `${words(20, 'keep')} new ${words(20, 'tail')}`,
    )
