    openReadySuggestion(handle)

    escapeAtCursor(handle)
    expect(escapeAtCursor(handle)).toBe(true)

    expect(suggestionsOf(handle.state).items).toEqual([])
  })

  it('rejects straight away when no bubble is open', () => {
